      [attr.aria-valuemax]="max()"
      class="progress"
      [class.progress--horizontal]="orientation() === 'horizontal'"
      [class.progress--vertical]="orientation() === 'vertical'"
      [class.progress--disabled]="disabled()"
      [class.progress--readonly]="readonly()"
    >
