import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  computed,
  viewChild,
  ElementRef,
} from '@angular/core';

@Component({
  selector: 'ui-slider',
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './Slider.css',
  template: `
    <div
      class="slider"
      [class.slider--vertical]="orientation() === 'vertical'"
      [class.slider--horizontal]="orientation() === 'horizontal'"
      [class.slider--disabled]="disabled()"
    >
      @if (label()) {
        <span class="slider__label">{{ label() }}</span>
      }
      <span class="slider__value">{{ currentValue() }}</span>
      <div
        role="group"
        class="slider__control"
        [class.slider__control--disabled]="disabled()"
        (pointerdown)="handlePointerDown($event)"
        (pointermove)="handlePointerMove($event)"
        (pointerup)="handlePointerUp($event)"
      >
        <div
          #trackEl
          class="slider__track"
          [class.slider__track--vertical]="orientation() === 'vertical'"
          [class.slider__track--horizontal]="orientation() === 'horizontal'"
        >
          <div
            class="slider__range"
            [class.slider__range--vertical]="orientation() === 'vertical'"
            [class.slider__range--horizontal]="orientation() === 'horizontal'"
            [class.slider__range--disabled]="disabled()"
            [style]="orientation() === 'vertical' ? 'height:' + percent() + '%' : 'width:' + percent() + '%'"
          ></div>
        </div>
        <div
          role="slider"
          [attr.tabindex]="disabled() ? -1 : 0"
          [attr.aria-valuemin]="min()"
          [attr.aria-valuemax]="max()"
          [attr.aria-valuenow]="currentValue()"
          [attr.aria-orientation]="orientation()"
          [attr.aria-disabled]="disabled() ? 'true' : null"
          (keydown)="handleKeyDown($event)"
          class="slider__thumb"
          [class.slider__thumb--vertical]="orientation() === 'vertical'"
          [class.slider__thumb--horizontal]="orientation() === 'horizontal'"
          [class.slider__thumb--disabled]="disabled()"
          [style]="orientation() === 'vertical' ? 'top:' + (100 - percent()) + '%' : 'left:' + percent() + '%'"
        ></div>
      </div>
    </div>
  `
})
export class Slider {
  value = input<number[]>();
  disabled = input(false);
  min = input(0);
  max = input(100);
  step = input(1);
  orientation = input<'horizontal' | 'vertical'>('horizontal');
  label = input<string>();
  valueChange = output<{ value: number[] }>();

  private trackEl = viewChild<ElementRef<HTMLDivElement>>('trackEl');

  protected currentValue = computed(() => this.value()?.[0] ?? this.min());

  protected percent = computed(() => {
    const range = this.max() - this.min() || 1;
    return Math.min(100, Math.max(0, ((this.currentValue() - this.min()) / range) * 100));
  });

  private clampVal(v: number) {
    return Math.min(this.max(), Math.max(this.min(), v));
  }

  private snapToStep(raw: number) {
    const steps = Math.round((raw - this.min()) / this.step());
    const snapped = this.min() + steps * this.step();
    return this.clampVal(Number(snapped.toFixed(10)));
  }

  private commit(next: number) {
    if (next === this.currentValue()) return;
    this.valueChange.emit({ value: [next] });
  }

  private valueFromPointer(clientX: number, clientY: number) {
    const el = this.trackEl()?.nativeElement;
    if (!el) return this.currentValue();
    const rect = el.getBoundingClientRect();
    const range = this.max() - this.min() || 1;
    const ratio = this.orientation() === 'vertical'
      ? 1 - (clientY - rect.top) / (rect.height || 1)
      : (clientX - rect.left) / (rect.width || 1);
    return this.snapToStep(this.min() + Math.min(1, Math.max(0, ratio)) * range);
  }

  protected handlePointerDown(e: PointerEvent) {
    if (this.disabled()) return;
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    this.commit(this.valueFromPointer(e.clientX, e.clientY));
  }

  protected handlePointerMove(e: PointerEvent) {
    if (this.disabled() || !(e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId)) return;
    this.commit(this.valueFromPointer(e.clientX, e.clientY));
  }

  protected handlePointerUp(e: PointerEvent) {
    if ((e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId)) {
      (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
    }
  }

  protected handleKeyDown(e: KeyboardEvent) {
    if (this.disabled()) return;
    let next = this.currentValue();
    switch (e.key) {
      case 'ArrowRight':
      case 'ArrowUp':
        next = this.clampVal(this.currentValue() + this.step());
        break;
      case 'ArrowLeft':
      case 'ArrowDown':
        next = this.clampVal(this.currentValue() - this.step());
        break;
      case 'Home':
        next = this.min();
        break;
      case 'End':
        next = this.max();
        break;
      default:
        return;
    }
    e.preventDefault();
    this.commit(this.snapToStep(next));
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  input,
  signal,
  OnInit,
  OnDestroy,
} from '@angular/core';

interface SpringConfig {
  target: number;
  damping: number;
  stiffness: number;
}

@Component({
  selector: 'ui-spring-oscillator',
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './SpringOscillator.css',
  template: `
    <div class="spring-oscillator">
      <div class="spring-oscillator__track">
        <div
          class="spring-oscillator__knob"
          [style.transform]="'translateX(' + x() + 'px)'"
        ></div>
      </div>
    </div>
  `
})
export class SpringOscillator implements OnInit, OnDestroy {
  spanPx = input(56);

  protected x = signal(0);

  private raf = 0;
  private position = 0;
  private velocity = 0;
  private stepIndex = 0;
  private lastTime = 0;

  private tick = (now: number) => {
    const sequence: SpringConfig[] = [
      { target: this.spanPx(), damping: 8, stiffness: 140 },
      { target: -this.spanPx(), damping: 8, stiffness: 140 },
      { target: 0, damping: 12, stiffness: 180 },
    ];
    const dt = Math.min((now - this.lastTime) / 1000, 1 / 30);
    this.lastTime = now;
    const cfg = sequence[this.stepIndex];
    const force = -cfg.stiffness * (this.position - cfg.target) - cfg.damping * this.velocity;
    this.velocity += force * dt;
    this.position += this.velocity * dt;
    const settled =
      Math.abs(this.position - cfg.target) < 0.5 && Math.abs(this.velocity) < 0.5;
    if (settled) {
      this.position = cfg.target;
      this.velocity = 0;
      this.stepIndex = (this.stepIndex + 1) % sequence.length;
    }
    this.x.set(this.position);
    this.raf = requestAnimationFrame(this.tick);
  };

  ngOnInit() {
    this.position = 0;
    this.velocity = 0;
    this.stepIndex = 0;
    this.lastTime = performance.now();
    this.raf = requestAnimationFrame(this.tick);
  }

  ngOnDestroy() {
    cancelAnimationFrame(this.raf);
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  computed,
} from '@angular/core';

interface TimeValue {
  hour: number;
  minute: number;
  second?: number;
}

@Component({
  selector: 'ui-time-field',
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './TimeField.css',
  template: `
    <div class="time-field">
      @if (label()) {
        <label class="time-field__label">
          {{ label() }}
          @if (required()) {
            <span class="time-field__required">*</span>
          }
        </label>
      }
      <div class="time-field__wrapper" [class.time-field__wrapper--disabled]="disabled()">
        <input
          type="time"
          class="time-field__input"
          [class.time-field__input--disabled]="disabled()"
          [value]="value()"
          (change)="handleChange($event)"
          [attr.name]="name() ?? null"
          [attr.required]="required() || null"
          [disabled]="disabled()"
          [attr.readonly]="readonly() || null"
          [attr.step]="allowSeconds() ? '1' : null"
          [attr.placeholder]="placeholder() ?? null"
          [attr.min]="min() ?? null"
          [attr.max]="max() ?? null"
        />
        @if (showClear()) {
          <button
            type="button"
            class="time-field__clear"
            (click)="handleClear()"
            aria-label="Clear time"
          >×</button>
        }
      </div>
    </div>
  `
})
export class TimeField {
  value = input('');
  placeholder = input<string>();
  required = input(false);
  disabled = input(false);
  readonly = input(false);
  label = input<string>();
  name = input<string>();
  allowSeconds = input(false);
  min = input<string>();
  max = input<string>();
  valueChange = output<{ value: string; valueAsTime: TimeValue }>();

  protected showClear = computed(() => !!(this.value() && !this.disabled() && !this.readonly()));

  private parseTimeString(ts: string): TimeValue {
    const parts = ts.split(':');
    return {
      hour: parseInt(parts[0] || '0', 10),
      minute: parseInt(parts[1] || '0', 10),
      second: parts[2] ? parseInt(parts[2], 10) : undefined,
    };
  }

  protected handleChange(e: Event) {
    const newValue = (e.currentTarget as HTMLInputElement).value;
    this.valueChange.emit({ value: newValue, valueAsTime: this.parseTimeString(newValue) });
  }

  protected handleClear() {
    this.valueChange.emit({ value: '', valueAsTime: { hour: 0, minute: 0 } });
  }
}

import { Component, ChangeDetectionStrategy, input, output } from '@angular/core';

@Component({
  selector: 'ui-toggle',
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './Toggle.css',
  template: `
    <div class="toggle">
      <button
        type="button"
        [class.toggle__button--on]="pressed()"
        [class.toggle__button--off]="!pressed()"
        class="toggle__button"
        [attr.aria-pressed]="pressed()"
        [attr.aria-label]="label() ?? 'Toggle'"
        [disabled]="disabled()"
        [attr.name]="name() ?? null"
        (click)="handleClick()"
      >
        <div
          class="toggle__dot"
          [class.toggle__dot--on]="pressed()"
          [class.toggle__dot--off]="!pressed()"
        ></div>
      </button>
      @if (label()) {
        <span
          class="toggle__label"
          [class.toggle__label--disabled]="disabled()"
          [class.toggle__label--enabled]="!disabled()"
        >{{ label() }}</span>
      }
    </div>
  `
})
export class Toggle {
  pressed = input(false);
  disabled = input(false);
  name = input<string>();
  label = input<string>();
  pressedChange = output<boolean>();

  protected handleClick() {
    this.pressedChange.emit(!this.pressed());
  }
}

